def reverse_rings(grid):
    """Within each nonzero connected object of concentric rectangular rings, reverse the ring color order."""
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                depths={}
                for y,x in cells:
                    d=min(y-r0,r1-y,x-c0,c1-x)
                    depths.setdefault(d,grid[y][x])
                order=sorted(depths); mapping={depths[d]:order[-1-k] for k,d in enumerate(order)} if False else {depths[od]:depths[nd] for od,nd in zip(order,order[::-1])}
                for y,x in cells:
                    out[y][x]=mapping[grid[y][x]]
