def reverse_rings(grid):
    """Within each nonzero 4-connected object of nested layers, replace layer k's cells with the color of the k-th layer counted from the inside (layer colors reversed)."""
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rem=set(cells); layers=[]
                while rem:
                    rs=[c[0] for c in rem]; cs=[c[1] for c in rem]
                    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                    outer={p for p in rem if min(p[0]-r0,r1-p[0],p[1]-c0,c1-p[1])==0}
                    layers.append(outer); rem-=outer
                for k,l in enumerate(layers):
                    c=layers[len(layers)-1-k]
                    col={grid[y][x] for y,x in c}.pop()
                    for y,x in l: out[y][x]=col
    return out

