def peel_layers(grid, cells):
    """The nested layers of an object, outside in: repeatedly the cells on the current bounding-box perimeter."""
    rem = set(cells); layers = []
    while rem:
        rs = [c[0] for c in rem]; cs = [c[1] for c in rem]
